const $=s=>document.querySelector(s);const app=$('#app'),nav=$('#nav');
function migrateV5Path(i){let oldName=OLD_V5_PATHS[Number(i)||0]||'Frontend Developer';if(oldName==='Cyber Security')oldName='Cybersecurity Basics';let mapped=PATHS.findIndex(p=>p[0]===oldName);return mapped>=0?mapped:3}
const defaultState={name:'',username:'',passwordDemo:'',path:0,level:0,done:{},xp:0,lang:'en',bookmarks:[],codes:{html:'<h1>Hello, coder!</h1>\n<p>Edit this page, then run it.</p>\n<button id="hello">Click me</button>',css:'body { font-family: Arial; padding: 24px; color: #263449; }\nh1 { color: #635bff; }\nbutton { padding: 10px 16px; }',js:'document.querySelector("#hello").addEventListener("click", () => {\n  document.querySelector("h1").textContent = "It works!";\n});'},activeTab:'html',lastCourse:0,completedQuiz:{}};
let state={...defaultState};try{const v6=JSON.parse(localStorage.getItem('veeku_v6')||'null');if(v6)state={...state,...v6};else{const v5=JSON.parse(localStorage.getItem('veeku_v5')||'null');if(v5){state={...state,name:v5.name||'',path:migrateV5Path(v5.path),level:v5.level||0,xp:v5.xp||0};state.done={...(v5.done||{})};}}}catch(e){}
function save(){try{localStorage.setItem('veeku_v6',JSON.stringify(state));return true}catch(e){toast('Could not save: browser storage may be full.');return false}}
function esc(x){return String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function t(k){return state.lang==='hi'?(TRANSLATIONS[k]||k):({translate:'Translate Everything to Hindi',home:'Home',courses:'Courses',editor:'Editor',profile:'Profile'}[k]||k)}
function toast(s){let n=$('#toast');if(!n){n=document.createElement('div');n.id='toast';n.style.cssText='position:fixed;left:50%;bottom:85px;transform:translateX(-50%);z-index:60;background:#20324e;border:1px solid #587096;padding:11px 16px;border-radius:10px;max-width:90vw;color:white';document.body.append(n)}n.textContent=s;n.hidden=false;clearTimeout(window.__toastTimer);window.__toastTimer=setTimeout(()=>n.hidden=true,2600)}
function header(){return `<div class="row"><div class="brand"><span class="brand-mark">&lt;/&gt;</span><span>VIKKU</span> CODE ACADEMY <span class="pill">V6</span></div><button class="btn ghost small" onclick="toggleLanguage()">${state.lang==='hi'?'Show in English':'Translate Everything to Hindi'}</button></div>`}
function setNav(show=true){nav.hidden=!show}
function topicFor(pathIndex,topicIndex){let name=PATHS[pathIndex][0],topics=TOPICS[name]||TOPICS['Software Engineer'];return topics[topicIndex%topics.length]}
function levelData(pathIndex,levelIndex){let name=PATHS[pathIndex][0],topics=TOPICS[name]||TOPICS['Software Engineer'],topic=topics[Math.floor(levelIndex/4)],phase=levelIndex%4;let phaseNames=['Understand the concept','Follow a guided example','Practise independently','Build a mini project'];let phases=['Concept','Guided practice','Independent practice','Mini project'];let descriptions=[`Learn what ${topic} means, the problem it solves, and the vocabulary used by developers.`,`Work through a guided ${topic.toLowerCase()} example. Read each part, predict what it does, then change one detail.`,`Use ${topic.toLowerCase()} without copying the example. Break the task into small steps and test your result.`,`Combine ${topic.toLowerCase()} with earlier skills in a small deliverable. Review, test and explain your decisions.`];let why=`${topic} is an important part of ${name}. It helps developers build software that is easier to understand, test and maintain.`;let where=`You will encounter ${topic.toLowerCase()} in real ${name.toLowerCase()} workflows, team projects and production software.`;let code=sampleFor(name,topic,phase);let explain=`Start with the smallest working idea. Identify the input, the operation and the expected result. Change one thing at a time, run a check, and read any error message carefully. In professional projects, keep names clear and separate unrelated responsibilities.`;let exercise=[`Identify the key idea in ${topic.toLowerCase()}. Write a short definition and point out where it appears in the example.`,`Follow the example for ${topic.toLowerCase()} one step at a time. Change one value or statement and predict the result before testing.`,`Write your own small implementation of ${topic.toLowerCase()} without copying the example. Test a normal case and one edge case.`,`Create a mini ${name.toLowerCase()} project that demonstrates ${topic.toLowerCase()}. Add a short note explaining your design choices.`][phase];let challenge=[`Explain when a developer would choose ${topic.toLowerCase()} and identify one mistake a beginner should avoid.`,`Modify the guided example so it solves a slightly different task while preserving the same core idea.`,`Solve a new task with ${topic.toLowerCase()} independently. Include a test that could reveal a mistake.`,`Build and review a small deliverable using ${topic.toLowerCase()}. Check expected behaviour, readability and one edge case.`][phase];let quiz=makeQuestion(name,topic,phase),questions=makeQuestionBank(name,topic,phase);return {name:topic,phase:phases[phase],phaseName:phaseNames[phase],description:descriptions[phase],why,where,code,explain,exercise,challenge,quiz,questions,objectives:[`Describe ${topic.toLowerCase()} in your own words`,`Recognize where it belongs in ${name}`,`Complete a small practical task`,`Check your work and explain the result`]};}
function sampleFor(path,topic,phase){if(path==='Flutter App Developer')return `void main() {\n  final scores = <int>[2, 4, 6];\n  final total = scores.reduce((a, b) => a + b);\n  print('$topic: $total');\n}`;if(path==='Android App Developer')return `fun main() {\n    val scores = listOf(2, 4, 6)\n    val total = scores.sum()\n    println(\"$topic: $total\")\n}`;if(path==='iOS App Developer')return `let scores = [2, 4, 6]\nlet total = scores.reduce(0, +)\nprint(\"$topic: \\(total)\")`;if(path==='Roblox Game Developer')return `-- ${topic}\nlocal scores = {2, 4, 6}\nlocal total = 0\nfor _, score in ipairs(scores) do\n    total += score\nend\nprint(\"Total: \" .. total)`;if(path==='Data Structures & Algorithms')return `# ${topic}\ndef binary_search(values, target):\n    left, right = 0, len(values) - 1\n    while left <= right:\n        middle = (left + right) // 2\n        if values[middle] == target:\n            return middle\n        if values[middle] < target:\n            left = middle + 1\n        else:\n            right = middle - 1\n    return -1`;if(path==='Godot Game Developer'){if(topic.includes('Signals'))return `# Signals and connections\nsignal health_changed(new_health)\n\nfunc take_damage(amount):\n    health -= amount\n    health_changed.emit(health)`;if(topic.includes('CharacterBody2D'))return `extends CharacterBody2D\n\n@export var speed := 220.0\nfunc _physics_process(delta):\n    var direction = Input.get_vector(\"ui_left\", \"ui_right\", \"ui_up\", \"ui_down\")\n    velocity = direction * speed\n    move_and_slide()`;if(topic.includes('Input'))return `func _process(_delta):\n    if Input.is_action_just_pressed(\"jump\"):\n        print(\"Jump pressed\")`;if(topic.includes('3D'))return `extends Node3D\n\n@onready var camera: Camera3D = $Camera3D\nfunc _ready():\n    print(\"3D scene ready\")`;return `extends Node2D\n\nfunc _ready():\n    print(\"${topic}\")\n\nfunc _process(delta):\n    # Add and test one small behaviour\n    pass`}if(path==='HTML & CSS Developer'){if(topic.includes('CSS')||topic.includes('Flexbox')||topic.includes('Grid')||topic.includes('Responsive')||topic.includes('Media')||topic.includes('Box')||topic.includes('Colors')||topic.includes('Pseudo')||topic.includes('focus')||topic.includes('variables')||topic.includes('position'))return `/* ${topic} */\n.container {\n  display: flex;\n  gap: 1rem;\n  padding: 1rem;\n  max-width: 60rem;\n  margin-inline: auto;\n}\n@media (max-width: 600px) {\n  .container { flex-direction: column; }\n}`;return `<!-- ${topic} -->\n<main>\n  <h1>My learning page</h1>\n  <p>Build clear, accessible page structure.</p>\n  <a href=\"#details\">Read more</a>\n  <section id=\"details\">\n    <h2>Details</h2>\n  </section>\n</main>`}if(path==='React Developer')return `function TopicCard({ title }) {\n  const [count, setCount] = React.useState(0);\n  return (\n    <section>\n      <h2>{title}</h2>\n      <button onClick={() => setCount(count + 1)}>\n        Count: {count}\n      </button>\n    </section>\n  );\n}`;if(path==='Node.js Developer'||path==='Backend Developer')return `// ${topic} · Node.js example\nimport http from 'node:http';\nconst server = http.createServer((req, res) => {\n  res.writeHead(200, { 'content-type': 'application/json' });\n  res.end(JSON.stringify({ status: 'ok' }));\n});\nserver.listen(3000);`;if(path==='TypeScript Developer')return `type Learner = { name: string; level: number };\nfunction welcome(user: Learner): string {\n  return "Hello " + user.name + ", level " + user.level;\n}\nconsole.log(welcome({ name: 'Ari', level: 1 }));`;if(path.includes('Python')||path==='Data Analyst'||path==='Data Scientist'||path==='AI & Machine Learning'||path==='Python Game Developer'){return `# ${topic}\nitems = [2, 4, 6]\ntotal = sum(items)\nprint("${topic}: ", total)\n\n# Try changing the values and observing the output.`}if(path.includes('Godot'))return `# ${topic}\nextends Node2D\n\nfunc _ready():\n    print("${topic}")\n\nfunc _process(delta):\n    # Add a small, testable behaviour here\n    pass`;if(path.includes('Java')||path.includes('Android'))return `// ${topic}\npublic class Main {\n    public static void main(String[] args) {\n        int[] values = {2, 4, 6};\n        int total = 0;\n        for (int value : values) total += value;\n        System.out.println("${topic}: " + total);\n    }\n}`;if(path.includes('C Developer'))return `/* ${topic} */\n#include <stdio.h>\n\nint main(void) {\n    int values[] = {2, 4, 6};\n    int total = 0;\n    for (int i = 0; i < 3; i++) total += values[i];\n    printf("${topic}: %d\\n", total);\n    return 0;\n}`;if(path.includes('C++'))return `// ${topic}\n#include <iostream>\n#include <vector>\nint main() {\n    std::vector<int> values{2, 4, 6};\n    int total = 0;\n    for (int value : values) total += value;\n    std::cout << "${topic}: " << total << '\\n';\n}`;if(path.includes('C#')||path.includes('Unity'))return `// ${topic}\nusing System;\nclass Program {\n    static void Main() {\n        int[] values = {2, 4, 6};\n        int total = 0;\n        foreach (int value in values) total += value;\n        Console.WriteLine("${topic}: " + total);\n    }\n}`;if(path.includes('SQL')||path.includes('Database'))return `-- ${topic}\nSELECT category, COUNT(*) AS item_count\nFROM learning_items\nGROUP BY category\nORDER BY item_count DESC;\n\n-- Try changing the grouping or filter.`;if(path.includes('Git'))return `# ${topic}\ngit status\ngit add .\ngit commit -m "Describe a small change"\ngit log --oneline\n\n# Inspect the result before pushing.`;if(path.includes('HTML')||path.includes('Frontend')||path.includes('React')||path.includes('Node')||path.includes('MERN')||path.includes('JavaScript')||path.includes('TypeScript'))return `// ${topic}\nconst values = [2, 4, 6];\nconst total = values.reduce((sum, value) => sum + value, 0);\nconsole.log("${topic}:", total);\n\n// Change the values and inspect the output.`;return `# ${topic}\n1. Identify the goal.\n2. Break it into smaller steps.\n3. Implement one step at a time.\n4. Test the expected result.\n\n# Write down what you learned.`}
function makeQuestion(path,topic,phase){let correct=`A focused way to understand and apply ${topic.toLowerCase()} in ${path}.`;let wrong=[`A visual theme that changes only the editor colour.`,`A timer that limits how long a learner can practise.`,`A shortcut that removes the need to test software.`];let options=[correct,...wrong];return {q:`Which statement best describes the learning goal for “${topic}”?`,options,correct:0,explain:`This level teaches ${topic.toLowerCase()} as a practical skill within ${path}. The other choices do not describe a software-development learning goal.`}}
function makeQuestionBank(path,topic,phase){return [
{q:`What is the main purpose of ${topic}?`,options:[`To solve a specific development problem in ${path}.`,`To decorate the code editor only.`,`To avoid checking whether code works.`,`To replace every other programming skill.`],correct:0,explain:`${topic} helps developers solve a specific problem as part of ${path}.`},
{q:`Why should a ${path} learner study ${topic}?`,options:[`It is a useful skill in the path's real development workflow.`,`It guarantees every program runs without errors.`,`It removes the need to understand requirements.`,`It is only useful for changing screen colours.`],correct:0,explain:`Learning ${topic} helps you understand and contribute to real ${path} work.`},
{q:`Which practice is the best way to learn ${topic}?`,options:[`Build a small example, change one part and test the result.`,`Copy a large project without reading it.`,`Skip testing and assume the result is correct.`,`Memorize the topic name without using it.`],correct:0,explain:`Small experiments help connect the concept to observable behaviour.`},
{q:`How can you check your work while practising ${topic}?`,options:[`Test a normal case and an edge case, then review the result.`,`Only check whether the editor has coloured text.`,`Avoid trying different inputs.`,`Delete the project whenever an error appears.`],correct:0,explain:`Testing expected and unusual cases helps reveal mistakes and improve reliability.`},
{q:`What should a completed ${topic} exercise demonstrate?`,options:[`A clear practical use of the topic and an explanation of the result.`,`A long file with no clear purpose.`,`A successful result that was never run or checked.`,`A feature unrelated to the selected career path.`],correct:0,explain:`A good exercise demonstrates the skill, produces a checked result and explains the approach.`}
]}
function validateQuestion(q){return !!q&&typeof q.q==='string'&&q.q.trim()&&Array.isArray(q.options)&&q.options.length===4&&q.options.every(x=>typeof x==='string'&&x.trim())&&new Set(q.options.map(x=>x.trim().toLowerCase())).size===4&&Number.isInteger(q.correct)&&q.correct>=0&&q.correct<4}
function shuffle(a){let x=[...a];for(let i=x.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[x[i],x[j]]=[x[j],x[i]]}return x}
function toggleLanguage(){if(currentView==='editor')collectCode();state.lang=state.lang==='hi'?'en':'hi';save();nav.querySelectorAll('[data-i18n]').forEach(el=>el.textContent=t(el.dataset.i18n));renderCurrent()}
function renderCurrent(){if(currentView==='home')render();else if(currentView==='path')renderPath();else if(currentView==='lesson')lessonScreen();else if(currentView==='quiz')quizScreen();else if(currentView==='levels')levelMap();else if(currentView==='courses')courseMap();else if(currentView==='editor')openEditor(true);else if(currentView==='profile')profile();else dashboard()}
let currentView='home',currentQuizOrder=[];
function login(){let n=$('#username')?.value.trim();if(!n){toast('Please enter a username.');return}state.username=n;state.name=n;save();renderPath()}
function render(){currentView='home';setNav(false);app.innerHTML=header()+`<section class="hero"><span class="eyebrow">Learn by building · V6</span><h1>From your first line of code to your first real project.</h1><p>A structured coding academy with career-focused paths, hands-on practice and progress that moves at your pace.</p><div class="toolbar"><span class="tag">30 career paths</span><span class="tag">100 levels per path</span><span class="tag">No countdowns</span></div></section><div class="grid"><section class="card"><h2>Welcome to VIKKU</h2><p>Sign in with a demo profile on this device or create a new local profile.</p><label class="field">${t('username')}</label><input class="input" id="username" maxlength="32" placeholder="e.g. coder_01" value="${esc(state.username)}"><label class="field">${t('password')} <span class="hint">(demo only; not securely stored)</span></label><input class="input" id="password" type="password" maxlength="80" placeholder="Optional demo password"><button class="btn full" onclick="login()">${t('login')}</button><p class="hint">This static version has no server authentication. Do not use a real password.</p></section><section class="card"><span class="eyebrow">What's included</span><h2>Learn with a clear roadmap</h2><p>Each path contains 25 technical topics, each explored through four stages: concept, guided practice, independent practice and a mini project.</p><p>That creates 100 structured levels per career path. Your progress is saved locally in this browser.</p></section></div>`}
function renderPath(){currentView='path';setNav(false);app.innerHTML=header()+`<span class="eyebrow">${t('choosePath')}</span><h1>${state.lang==='hi'?'आप कौन-सा Developer Path सीखना चाहते हैं?':'Which developer path interests you?'}</h1><p>${state.lang==='hi'?'अभी एक पाथ चुनें। बाद में इसे बदलने पर आपके पूरे हुए लेवल नहीं मिटेंगे।':'Choose one now. You can change it later without deleting completed lessons.'}</p><input class="input" id="pathSearch" placeholder="${t('search')}" oninput="filterPaths(this.value)" style="margin:14px 0"><div id="pathGrid" class="path-grid">${PATHS.map((p,i)=>pathCard(p,i)).join('')}</div><button class="btn full" onclick="dashboard()">${t('continuePath')}: ${esc(PATHS[state.path][0])} →</button>`}
function pathCard(p,i){return `<button class="path-card ${state.path===i?'selected':''}" data-path="${i}" onclick="selectPath(${i})"><span class="ico">${p[1]}</span><strong>${esc(p[0])}</strong><small>${esc(p[2])}</small></button>`}
function selectPath(i){state.path=i;save();if(currentView==='courses'){levelMap();return}document.querySelectorAll('.path-card').forEach(x=>x.classList.toggle('selected',Number(x.dataset.path)===i));let b=document.querySelector('#pathGrid')?.parentElement?.querySelector('.btn.full');if(b)b.textContent='Continue with '+PATHS[i][0]+' →'}
function filterPaths(q){let s=q.toLowerCase();document.querySelectorAll('.path-card').forEach(el=>{el.hidden=!PATHS[+el.dataset.path].join(' ').toLowerCase().includes(s)})}
function dashboard(){currentView='dashboard';setNav(true);let total=Object.keys(state.done).filter(k=>state.done[k]).length,currentDone=Object.keys(state.done).filter(k=>k.startsWith(state.path+'_')&&state.done[k]).length;app.innerHTML=header()+`<div class="row"><div><span class="eyebrow">${t('dashboard')}</span><h1>${t('welcome')}, ${esc(state.name||'Learner')}.</h1></div><span class="pill">⭐ ${state.xp} XP</span></div><section class="card"><div class="row"><div><span class="eyebrow">${t('career')}</span><h2>${PATHS[state.path][1]} ${esc(PATHS[state.path][0])}</h2><p>${esc(PATHS[state.path][2])}</p></div><button class="btn secondary small" onclick="renderPath()">${t('changePath')}</button></div><div class="progress"><i style="width:${currentDone}%"></i></div><p>${currentDone}/100 levels completed in this path · ${total} total across all paths</p><div class="toolbar"><button class="btn" onclick="continueLearning()">${t('continue')} →</button><button class="btn secondary" onclick="courseMap()">${t('browsePaths')}</button></div></section><div class="grid"><div class="card"><span class="eyebrow">Practice</span><h2>⌘ ${t('playground')}</h2><p>${state.lang==='hi'?'HTML, CSS और JavaScript लिखें और ब्राउज़र में उसका परिणाम देखें।':'Write and run HTML, CSS and JavaScript in a sandboxed browser preview.'}</p><button class="btn secondary full" onclick="openEditor()">${t('openEditor')}</button></div><div class="card"><span class="eyebrow">Your activity</span><h2>⭐ ${state.xp} XP</h2><p>${state.bookmarks.length} bookmarked levels · ${total} completed levels</p><button class="btn secondary full" onclick="profile()">View profile</button></div></div><div class="card"><h3>Learning promise</h3><p>No countdown timer, no lesson expiration and no forced daily streak. Wrong answers do not erase earlier progress.</p></div>`}
function courseMap(){currentView='courses';setNav(true);app.innerHTML=header()+`<span class="eyebrow">Learning library</span><h1>30 career paths</h1><p>Each path has its own technology-specific roadmap. Select one to see its 100-level map.</p><div class="path-grid">${PATHS.map((p,i)=>pathCard(p,i)).join('')}</div>`}
function levelMap(){currentView='levels';setNav(true);let p=PATHS[state.path],levels=Array.from({length:100},(_,i)=>{let d=levelData(state.path,i),key=state.path+'_'+i,done=!!state.done[key],allowed=i===0||!!state.done[state.path+'_'+(i-1)];return `<button class="level-item ${done?'done':''} ${i===getNextLevel()?'current':''}" ${allowed?'':'disabled'} onclick="openLesson(${i})"><b>${done?'✓ ':''}${i+1}</b><small>${esc(d.name)}</small><small>${done?'Completed':allowed?'Available':'Locked'}</small></button>`}).join('');app.innerHTML=header()+`<div class="row"><div><span class="eyebrow">${esc(p[0])}</span><h1>${state.lang==='hi'?'100 लेवल का रोडमैप':'100-level roadmap'}</h1></div><button class="btn ghost small" onclick="renderPath()">Change path</button></div><p>Four stages for each of 25 path-specific topics. Complete at your own pace.</p><div class="toolbar"><span class="pill">${t('beginner')} · 1–25</span><span class="pill">${t('intermediate')} · 26–50</span><span class="pill">${t('advanced')} · 51–75</span><span class="pill">${t('professional')} · 76–100</span></div><div class="progress"><i style="width:${Object.keys(state.done).filter(k=>k.startsWith(state.path+'_')&&state.done[k]).length}%"></i></div><div class="level-list">${levels}</div><div class="card"><h3>Progress summary</h3><p>${Object.keys(state.done).filter(k=>k.startsWith(state.path+'_')&&state.done[k]).length}/100 levels completed in ${esc(p[0])}.</p><button class="btn secondary" onclick="showCertificate()">View progress certificate</button></div>`}
function getNextLevel(){for(let i=0;i<100;i++)if(!state.done[state.path+'_'+i])return i;return 99}
function continueLearning(){let i=getNextLevel();if(state.done[state.path+'_'+i])showCertificate();else openLesson(i)}
let activeLevel=0,currentQuestionIndex=0;
function openLesson(i){activeLevel=Math.max(0,Math.min(99,i));currentView='lesson';lessonScreen()}
function lessonContent(d,key){if(state.lang!=='hi')return d[key];let n=d.name;const hi={description:`इस चरण में ${n} का अर्थ, इसका उद्देश्य और इससे जुड़ी मुख्य बातें सीखें।`,why:`${n} ${PATHS[state.path][0]} का एक महत्वपूर्ण हिस्सा है। इससे ऐसे सॉफ्टवेयर बनाना आसान होता है जिसे समझना, जाँचना और सुधारना आसान हो।`,where:`${n} का उपयोग ${PATHS[state.path][0]} के वास्तविक प्रोजेक्ट, टीम के काम और सॉफ्टवेयर में होता है।`,explain:`सबसे छोटे काम करने वाले उदाहरण से शुरुआत करें। इनपुट, प्रक्रिया और अपेक्षित परिणाम पहचानें। एक बार में एक बदलाव करें और जाँचें। Error आए तो उसका संदेश पढ़ें और कारण खोजें।`,exercise:`${n} दिखाने वाला छोटा उदाहरण खुद लिखें। साफ नाम रखें, एक उपयोगी टिप्पणी जोड़ें और परिणाम जाँचें।`,challenge:`${PATHS[state.path][0]} के लिए ${n} का उपयोग करके छोटा फीचर बनाएँ। सामान्य स्थिति और एक विशेष स्थिति दोनों जाँचें।`,objectives:[`${n} को अपने शब्दों में समझाएँ`,`${PATHS[state.path][0]} में इसका उपयोग पहचानें`,`छोटा व्यावहारिक काम पूरा करें`,`अपने परिणाम की जाँच करें`]};return hi[key]||d[key]}
function lessonScreen(){setNav(true);let d=levelData(state.path,activeLevel),p=PATHS[state.path],key=state.path+'_'+activeLevel,book=state.bookmarks.includes(key);app.innerHTML=header()+`<div class="row"><button class="btn ghost small" onclick="levelMap()">← ${t('levels')}</button><div class="toolbar"><span class="pill">${esc(p[0])}</span><span class="pill">Level ${activeLevel+1}/100</span><button class="bookmark" title="Bookmark" onclick="toggleBookmark('${key}')">${book?'★':'☆'}</button></div></div><div class="progress"><i style="width:${(activeLevel+1)}%"></i></div><section class="lesson"><span class="eyebrow">${state.lang==='hi'?['कॉन्सेप्ट','गाइडेड अभ्यास','स्वयं अभ्यास','मिनी प्रोजेक्ट'][activeLevel%4]:esc(d.phase)} · ${activeLevel<25?t('beginner'):activeLevel<50?t('intermediate'):activeLevel<75?t('advanced'):t('professional')}</span><h1>${esc(d.name)}</h1><h3>${state.lang==='hi'?['कॉन्सेप्ट समझें','उदाहरण के साथ अभ्यास','खुद अभ्यास करें','मिनी प्रोजेक्ट'][activeLevel%4]:esc(d.phaseName)}</h3><p>${esc(lessonContent(d,'description'))}</p><div class="info"><b>${t('why')}</b><br>${esc(lessonContent(d,'why'))}</div><div class="info"><b>${t('where')}</b><br>${esc(lessonContent(d,'where'))}</div><h3>${t('code')}</h3><pre><code>${esc(d.code)}</code></pre><button class="btn secondary" onclick="explainLessonCode()">${state.lang==='hi'?'इस कोड को समझें':'Explain this code'}</button><h3>${t('explanation')}</h3><p>${esc(lessonContent(d,'explain'))}</p><div class="info"><b>${t('exercise')}</b><br>${esc(lessonContent(d,'exercise'))}</div><div class="info"><b>${t('challenge')}</b><br>${esc(lessonContent(d,'challenge'))}</div><h3>${t('objective')}</h3><ul>${lessonContent(d,'objectives').map(x=>`<li>${esc(x)}</li>`).join('')}</ul><button class="btn secondary" onclick="showHindiExplanation()">${t('explanation')} · हिंदी</button><div id="hiExplain" class="info hidden">${esc(hindiExplanation(d))}</div><button class="btn full" onclick="startQuiz()">${t('quiz')} · Start knowledge check</button></section>`}
function hindiExplanation(d){return `इस पाठ में ${d.name} सीखेंगे। इसका मतलब है कि आप इस तकनीक के उद्देश्य को समझेंगे, एक उदाहरण देखेंगे और फिर खुद अभ्यास करेंगे। पहले छोटा हिस्सा बनाइए, फिर उसे चलाकर जाँचिए। गलती आए तो संदेश पढ़कर एक-एक बदलाव करें।`}
function showHindiExplanation(){$('#hiExplain')?.classList.toggle('hidden')}
function toggleBookmark(key){let i=state.bookmarks.indexOf(key);if(i<0)state.bookmarks.push(key);else state.bookmarks.splice(i,1);save();lessonScreen()}
function startQuiz(){currentView='quiz';currentQuestionIndex=0;let bank=levelData(state.path,activeLevel).questions;if(!Array.isArray(bank)||bank.length!==5||!bank.every(validateQuestion)){toast('This question set did not pass validation. Return to the lesson.');lessonScreen();return}currentQuizOrder=shuffle([0,1,2,3]);quizScreen()}
function currentQuestion(){let d=levelData(state.path,activeLevel),q=d.questions[currentQuestionIndex];if(state.lang==='hi'){const hindiQuestions=[`“${d.name}” का मुख्य उद्देश्य क्या है?`,`इस करियर में ${d.name} सीखना क्यों उपयोगी है?`,`इस विषय को सीखने का सबसे अच्छा तरीका क्या है?`,`अपने अभ्यास की जाँच कैसे करनी चाहिए?`,`एक अच्छा ${d.name} अभ्यास क्या दिखाना चाहिए?`];const hindiOptions=[`${d.name} ${PATHS[state.path][0]} में एक खास विकास समस्या हल करने में मदद करता है।`,`यह केवल एडिटर का रंग बदलता है।`,`इससे कोड जाँचे बिना सही मान लिया जाता है।`,`यह बाकी सभी प्रोग्रामिंग कौशल की जगह लेता है।`];const opts=[hindiOptions,[`${PATHS[state.path][0]} के वास्तविक काम में यह उपयोगी कौशल है।`,'यह हर प्रोग्राम को बिना गलती के चलाने की गारंटी देता है।','इससे requirements समझने की जरूरत खत्म हो जाती है।','यह केवल स्क्रीन का रंग बदलने के काम आता है।'],['छोटा उदाहरण बनाएँ, एक बदलाव करें और परिणाम जाँचें।','बिना पढ़े पूरा बड़ा प्रोजेक्ट कॉपी करें।','टेस्ट किए बिना परिणाम को सही मान लें।','सिर्फ विषय का नाम याद करें।'],['सामान्य और कठिन दोनों स्थितियों में टेस्ट करें।','केवल एडिटर के रंग देखें।','अलग-अलग input आजमाने से बचें।','Error आने पर पूरा प्रोजेक्ट मिटा दें।'],[`${d.name} का सही उपयोग और परिणाम की साफ व्याख्या।`,'बिना उद्देश्य वाली लंबी फाइल।','ऐसा परिणाम जिसे कभी चलाकर जाँचा न गया हो।','चुने हुए करियर से असंबंधित फीचर।']];q={...q,q:hindiQuestions[currentQuestionIndex],options:opts[currentQuestionIndex],explain:`${d.name} ${PATHS[state.path][0]} के काम में उपयोगी कौशल है। छोटे उदाहरण और टेस्ट से इसकी समझ मजबूत होती है।`}}return q}
function quizScreen(){setNav(true);let d=levelData(state.path,activeLevel),q=currentQuestion();if(!validateQuestion(q)){app.innerHTML=header()+`<div class="card"><h2>Question validation failed</h2><p>No invalid question will be shown. Return to the lesson and retry.</p><button class="btn" onclick="lessonScreen()">Back to lesson</button></div>`;return}app.innerHTML=header()+`<button class="btn ghost small" onclick="lessonScreen()">← ${t('back')}</button><section class="lesson"><span class="eyebrow">${state.lang==='hi'?'ज्ञान जाँच':'Knowledge check'} · ${currentQuestionIndex+1}/5 · Level ${activeLevel+1}</span><div class="progress"><i style="width:${(currentQuestionIndex+1)*20}%"></i></div><h2>${esc(q.q)}</h2>${currentQuizOrder.map((n,i)=>`<button class="quiz-option" id="opt${n}" onclick="answerQuiz(${n})"><b>${String.fromCharCode(65+i)}.</b> ${esc(q.options[n])}</button>`).join('')}<div id="quizFeedback"></div></section>`}
function retryCurrentQuestion(){currentQuizOrder=shuffle([0,1,2,3]);quizScreen()}
function nextQuizQuestion(){currentQuestionIndex++;if(currentQuestionIndex>=5){completeLevel();return}currentQuizOrder=shuffle([0,1,2,3]);quizScreen()}
function answerQuiz(n){let q=currentQuestion(),fb=$('#quizFeedback');if(!fb||fb.dataset.answered)return;fb.dataset.answered='1';document.querySelectorAll('.quiz-option').forEach((b)=>b.disabled=true);if(n===q.correct){$('#opt'+n).classList.add('correct');fb.innerHTML=`<div class="feedback good">✓ ${t('correct')} ${esc(q.explain)}</div><button class="btn full" onclick="nextQuizQuestion()">${currentQuestionIndex===4?t('complete'):(state.lang==='hi'?'अगला सवाल':'Next question')} →</button>`}else{$('#opt'+n).classList.add('wrong');$('#opt'+q.correct).classList.add('correct');fb.innerHTML=`<div class="feedback bad">${t('incorrect')}<br>${esc(q.explain)}</div><button class="btn secondary" onclick="retryCurrentQuestion()">${t('retry')}</button><button class="btn ghost" onclick="lessonScreen()">Review lesson</button>`}}
function completeLevel(){let key=state.path+'_'+activeLevel;if(!state.done[key]){state.done[key]=true;state.xp+=20}state.completedQuiz[key]=true;save();if(activeLevel<99){activeLevel++;levelMap();toast('+20 XP · Next level unlocked')}else{showCertificate()}}
function showCertificate(){let done=Object.keys(state.done).filter(k=>k.startsWith(state.path+'_')&&state.done[k]).length;app.innerHTML=header()+`<div class="cert"><span class="eyebrow">VIKKU CODE ACADEMY · LEARNING RECORD</span><h1>Progress Certificate</h1><p>This recognises the learning progress of</p><h2>${esc(state.name||'Learner')}</h2><p>Career path: <b>${esc(PATHS[state.path][0])}</b></p><h2>${done} / 100 levels completed</h2><p>This is a local progress summary, not an accredited qualification.</p><button class="btn" onclick="levelMap()">Back to roadmap</button></div>`}
function profile(){currentView='profile';setNav(true);let done=Object.keys(state.done).filter(k=>state.done[k]).length;app.innerHTML=header()+`<span class="eyebrow">Learner profile</span><h1>${esc(state.name||'Learner')}</h1><div class="grid"><div class="card"><h2>⭐ ${state.xp} XP</h2><p>Earned by completing learning levels.</p></div><div class="card"><h2>${done} levels</h2><p>Completed across all career paths.</p></div></div><div class="card"><h3>Achievements</h3><div class="toolbar">${done>=1?'<span class="pill">🌱 First level</span>':''}${done>=10?'<span class="pill">🔥 10 levels</span>':''}${done>=25?'<span class="pill">🏅 25 levels</span>':''}${done>=50?'<span class="pill">🚀 50 levels</span>':''}${done>=100?'<span class="pill">👑 100 levels</span>':''}${done===0?'<span class="pill">Complete a level to earn your first achievement</span>':''}</div></div><div class="card"><h3>${t('bookmarks')}</h3>${state.bookmarks.length?state.bookmarks.map(k=>{let [pi,li]=k.split('_').map(Number);return `<p>${esc(PATHS[pi]?.[0]||'Path')} · Level ${li+1} <button class="btn small secondary" onclick="state.path=${pi};save();openLesson(${li})">Open</button></p>`}).join(''):'<p>No bookmarked levels yet.</p>'}</div><div class="card"><h3>Account and data</h3><p>This is a local demo profile. Username and progress stay in this browser's local storage. There is no secure server login, cloud sync or password hashing.</p><button class="btn secondary" onclick="if(confirm('Sign out of this local profile? Your saved progress will remain on this device.')){state.name='';state.username='';save();render()} ">Log out</button><button class="btn pink" onclick="if(confirm('Delete all V6 local progress on this device?')){localStorage.removeItem('veeku_v6');location.reload()}">Reset local progress</button></div>`}
let editors={},activeTab='html',editorFallback=false;
function editorSample(tab){return state.codes[tab]??defaultState.codes[tab]}
function openEditor(keep=false){currentView='editor';setNav(true);app.innerHTML=header()+`<div class="row"><div><span class="eyebrow">${state.lang==='hi'?'सीखें और खुद बनाएं':'LEARN BY BUILDING'}</span><h1>${t('playground')}</h1><p>${state.lang==='hi'?'कोड लिखें, चलाएं और हर लाइन का मतलब हिंदी या English में समझें।':'Write code, run it and understand every line in Hindi or English.'}</p></div><span class="pill">HTML · CSS · JavaScript · Three.js</span></div><section class="workspace"><div class="toolbar"><button class="btn small" onclick="runCode()">▶ ${t('run')}</button><button class="btn secondary small" onclick="explainCode()">${state.lang==='hi'?'कोड समझाएं':'Explain code'}</button><button class="btn secondary small" onclick="insert3DStarter()">＋ 3D Starter</button><button class="btn secondary small" onclick="saveCode()">${t('save')}</button><button class="btn secondary small" onclick="loadCode()">Load saved</button><button class="btn ghost small" onclick="resetCode()">${t('reset')}</button><button class="btn ghost small" onclick="clearOutput()">Clear output</button></div><div class="workspace-grid" id="workspaceGrid"><div class="editor-pane"><h3>${t('editorPanel')}</h3><div class="editor-tabs">${['html','css','js'].map(x=>`<button id="tab-${x}" class="${activeTab===x?'active':''}" onclick="switchTab('${x}')">${x.toUpperCase()}</button>`).join('')}</div><textarea id="codearea" class="fallback-editor" spellcheck="false"></textarea><p class="hint">${state.lang==='hi'?'ऊपर का Explain Code बटन हर लाइन की आसान व्याख्या दिखाता है।':'Use Explain Code to get a simple line-by-line explanation.'}</p></div><div class="splitter" id="splitter" role="separator" aria-label="Resize editor and preview"></div><div class="preview-pane"><div class="row"><h3>${t('livePreview')}</h3><select id="previewMode" class="select" style="width:auto" onchange="setPreviewMode(this.value)"><option value="2d">2D Web Preview</option><option value="3d">3D Model · Three.js</option></select></div><iframe id="preview" class="preview" sandbox="allow-scripts"></iframe><h3 style="margin-top:12px">${t('output')}</h3><pre id="output" class="output">Ready. Press Run code.</pre></div></div><section id="codeExplainPanel" class="code-explain hidden"><div class="row"><h3>${state.lang==='hi'?'कोड की लाइन-दर-लाइन व्याख्या':'Line-by-line code explanation'}</h3><select id="explainLanguage" class="select" style="width:auto" onchange="explainCode()"><option value="hi" ${state.lang==='hi'?'selected':''}>हिंदी</option><option value="en" ${state.lang!=='hi'?'selected':''}>English</option></select></div><div id="explainContent"></div></section><p class="hint">${state.lang==='hi'?'ब्राउज़र में HTML/CSS/JavaScript और Three.js 3D Preview चलता है। अन्य भाषाओं के लिए अलग compiler/server चाहिए।':'HTML/CSS/JavaScript and Three.js run in this browser. Other languages need a separate compiler/server.'}</p></section>`;activeTab=state.activeTab||'html';initEditor();initSplitter();if(!keep)runCode()}
function initEditor(){editors={};let ta=$('#codearea');ta.value=editorSample(activeTab);if(window.CodeMirror){ta.classList.add('hidden');editors[activeTab]=CodeMirror.fromTextArea(ta,{lineNumbers:true,theme:'material-darker',mode:activeTab==='html'?'xml':activeTab==='css'?'css':'javascript',indentUnit:2,tabSize:2,lineWrapping:false});editors[activeTab].setSize('100%',310)}else{editorFallback=true;ta.classList.remove('hidden')} }
function readTab(tab){if(editors[tab])return editors[tab].getValue();if(tab===activeTab&&$('#codearea'))return $('#codearea').value;return editorSample(tab)}
function writeTab(tab,value){state.codes[tab]=value;if(tab===activeTab){if(editors[tab])editors[tab].setValue(value);else if($('#codearea'))$('#codearea').value=value}}
function switchTab(tab){state.codes[activeTab]=readTab(activeTab);if(editors[activeTab]){editors[activeTab].toTextArea();delete editors[activeTab]}activeTab=tab;state.activeTab=tab;let ta=$('#codearea');ta.classList.remove('hidden');ta.value=editorSample(tab);document.querySelectorAll('.editor-tabs button').forEach(b=>b.classList.toggle('active',b.id==='tab-'+tab));if(window.CodeMirror){ta.classList.add('hidden');editors[tab]=CodeMirror.fromTextArea(ta,{lineNumbers:true,theme:'material-darker',mode:tab==='html'?'xml':tab==='css'?'css':'javascript',indentUnit:2,tabSize:2,lineWrapping:false});editors[tab].setSize('100%',310)}else ta.classList.remove('hidden')}
function collectCode(){state.codes[activeTab]=readTab(activeTab);return {...state.codes}}
function saveCode(){collectCode();save();toast('Code saved on this device.')}
function loadCode(){try{let saved=JSON.parse(localStorage.getItem('veeku_v6')||'{}');if(saved.codes)state.codes={...defaultState.codes,...saved.codes};writeTab(activeTab,state.codes[activeTab]);toast('Saved code loaded.')}catch(e){toast('No valid saved code was found.')}}
function resetCode(){writeTab(activeTab,defaultState.codes[activeTab]);runCode()}
function clearOutput(){if($('#output'))$('#output').textContent='Output cleared.'}
function setPreviewMode(mode){if(mode==='3d'&&$('#output'))$('#output').textContent='3D mode selected. Use 3D Starter or write Three.js code, then press Run.';runCode()}
function runCode(){let c=collectCode(),frame=$('#preview');if(!frame)return;let safeJs=c.js.replace(/<\/script/gi,'<\\/script');let doc='<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><style>'+c.css+'</style></head><body>'+c.html+'<script>const send=(type,args)=>parent.postMessage({veekuPreview:true,type,args},"*");console.log=(...a)=>send("log",a);console.error=(...a)=>send("error",a);window.onerror=(m)=>send("error",[m]);<\/script><script>'+safeJs+'<\/script></body></html>';frame.srcdoc=doc;$('#output').textContent='Running preview…';window.addEventListener('message',function previewMessage(e){if(e.data&&e.data.veekuPreview){$('#output').textContent=(e.data.type==='error'?'Error: ':'')+e.data.args.map(x=>typeof x==='object'?JSON.stringify(x):String(x)).join(' ')}},{once:false});setTimeout(()=>{if($('#output')?.textContent==='Running preview…')$('#output').textContent='Preview loaded. Use the page to interact with your project.'},500);save()}
function initSplitter(){let s=$('#splitter'),g=$('#workspaceGrid');if(!s||!g)return;let down=false;s.onpointerdown=e=>{if(innerWidth<761)return;down=true;s.setPointerCapture(e.pointerId)};s.onpointermove=e=>{if(!down)return;let r=g.getBoundingClientRect(),pct=Math.max(25,Math.min(75,(e.clientX-r.left)/r.width*100));g.style.gridTemplateColumns=`minmax(220px,${pct}fr) 7px minmax(220px,${100-pct}fr)`};s.onpointerup=()=>down=false;s.onpointercancel=()=>down=false}




