function renderPath(){currentView='path';setNav(false);app.innerHTML=header()+`<section class="setup-wrap"><div class="setup-card wide"><div class="step-meta"><span>YOUR LEARNING PROFILE</span><b>STEP 2 OF 4</b></div><div class="step-track"><i style="width:50%"></i></div><span class="eyebrow">PICK YOUR DIRECTION</span><h1>Choose a developer path.</h1><p>Start with one path. You can explore other paths later.</p><input class="input path-search" id="pathSearch" placeholder="Search paths..." oninput="filterPaths(this.value)"><div id="pathGrid" class="path-grid">${PATHS.map((p,i)=>pathCard(p,i)).join('')}</div><div class="setup-actions"><button class="text-btn" onclick="showGoalSetup()">Back</button><button class="btn primary-cta" onclick="showSkillSetup()">Continue ${svgIcon('arrow')}</button></div></div></section>`}
function brandIcon(name){let n=name.toLowerCase(),label='DEV',cls='dev',slug='',hex='ffffff';
 if(n.includes('godot')){label='G';cls='godot';slug='godotengine';hex='478CBF'}else if(n.includes('javascript')){label='JS';cls='js';slug='javascript';hex='F7DF1E'}else if(n.includes('html')){label='5';cls='html';slug='html5';hex='E34F26'}else if(n.includes('css')){label='3';cls='css';slug='css3';hex='1572B6'}else if(n.includes('typescript')){label='TS';cls='ts';slug='typescript';hex='3178C6'}else if(n.includes('python')){label='Py';cls='python';slug='python';hex='3776AB'}else if(n.includes('react')){label='⚛';cls='react';slug='react';hex='61DAFB'}else if(n.includes('java developer')){label='J';cls='java';slug='openjdk';hex='ED8B00'}else if(n.includes('c++')){label='C++';cls='cpp';slug='cplusplus';hex='00599C'}else if(n.includes('c#')){label='C#';cls='csharp';slug='csharp';hex='512BD4'}else if(n.includes('sql')||n.includes('database')){label='DB';cls='sql';slug='mysql';hex='4479A1'}else if(n.includes('flutter')){label='F';cls='flutter';slug='flutter';hex='02569B'}else if(n.includes('android')){label='A';cls='android';slug='android';hex='3DDC84'}else if(n.includes('node')){label='JS';cls='node';slug='nodedotjs';hex='5FA04E'}else if(n.includes('unity')){label='U';cls='unity';slug='unity';hex='ffffff'}else if(n.includes('git')){label='◆';cls='git';slug='git';hex='F05032'}else if(n.includes('ai')||n.includes('machine')){label='AI';cls='ai'}else if(n.includes('cyber')){label='CS';cls='cyber'}else if(n.includes('data')){label='D';cls='data'}else if(n.includes('ios')){label='iOS';cls='ios';slug='swift';hex='F05138'}else if(n.includes('roblox')){label='R';cls='roblox';slug='roblox';hex='ffffff'}else if(n.includes('full stack')){label='FS';cls='fullstack'}else if(n.includes('backend')){label='API';cls='backend'}else if(n.includes('frontend')){label='UI';cls='frontend'}else if(n.includes('software engineer')){label='</>';cls='software'}else if(n.includes('c developer')){label='C';cls='clang';slug='c';hex='A8B9CC'}
 const image=slug?`<img src="https://cdn.simpleicons.org/${slug}/${hex}" alt="" loading="lazy" onerror="this.style.display='none'">`:'';
 return `<span class="brand-logo ${cls}" aria-label="${esc(name)} logo">${image}<span class="logo-fallback">${label}</span></span>`}
function pathCard(p,i){return `<button class="path-card ${state.path===i?'selected':''}" data-path="${i}" onclick="selectPath(${i})">${brandIcon(p[0])}<strong>${esc(p[0])}</strong><small>${esc(p[2])}</small></button>`}
function selectPath(i){state.path=i;save();document.querySelectorAll('.path-card').forEach(x=>x.classList.toggle('selected',Number(x.dataset.path)===i))}
function showSkillSetup(){onboardingStep=2;app.innerHTML=header()+`<section class="setup-wrap"><div class="setup-card"><div class="step-meta"><span>YOUR LEARNING PROFILE</span><b>STEP 3 OF 4</b></div><div class="step-track"><i style="width:75%"></i></div><span class="eyebrow">YOUR CURRENT EXPERIENCE</span><h1>Where are you starting from?</h1><p>We'll adjust your learning journey to match your experience.</p><div class="skill-options">${[['beginner','Complete beginner','I am new to coding.'],['intermediate','Know the basics','I have tried coding before.'],['advanced','Some experience','I can build small projects.']].map(x=>`<button class="skill-option ${state.skill===x[0]?'selected':''}" onclick="chooseSkill('${x[0]}',this)"><span>${svgIcon('target')}</span><div><b>${x[1]}</b><small>${x[2]}</small></div><span class="radio-dot"></span></button>`).join('')}</div><div class="setup-actions"><button class="text-btn" onclick="renderPath()">Back</button><button class="btn primary-cta" onclick="showDailySetup()">Continue ${svgIcon('arrow')}</button></div></div></section>`}
function chooseSkill(v,el){state.skill=v;document.querySelectorAll('.skill-option').forEach(x=>x.classList.remove('selected'));el.classList.add('selected');save()}
function showDailySetup(){app.innerHTML=header()+`<section class="setup-wrap"><div class="setup-card"><div class="step-meta"><span>YOUR LEARNING PROFILE</span><b>STEP 4 OF 4</b></div><div class="step-track"><i style="width:100%"></i></div><span class="eyebrow">A LITTLE PRACTICE EVERY DAY</span><h1>Set your daily goal.</h1><p>Pick a target that feels comfortable. You can change it anytime.</p><div class="goal-options">${[[5,'5 min','Easy start'],[15,'15 min','Balanced'],[30,'30 min','Focused'],[45,'45 min','Deep practice']].map(x=>`<button class="goal-option ${state.dailyGoal===x[0]?'selected':''}" onclick="chooseDaily(${x[0]},this)"><b>${x[1]}</b><small>${x[2]}</small></button>`).join('')}</div><div class="setup-actions"><button class="text-btn" onclick="showSkillSetup()">Back</button><button class="btn primary-cta" onclick="finishSetup()">Start my journey ${svgIcon('arrow')}</button></div></div></section>`}
function chooseDaily(v,el){state.dailyGoal=v;document.querySelectorAll('.goal-option').forEach(x=>x.classList.remove('selected'));el.classList.add('selected');save()}
function finishSetup(){state.onboardingComplete=true;save();dashboard();toast('Your learning journey is ready!')}
function dashboard(){currentView='dashboard';setNav(true);let total=Object.keys(state.done).filter(k=>state.done[k]).length,done=Object.keys(state.done).filter(k=>k.startsWith(state.path+'_')&&state.done[k]).length,level=Math.floor((state.xp||0)/100)+1,levelXp=(state.xp||0)%100;app.innerHTML=header()+`<section class="dash-welcome"><div><span class="eyebrow">YOUR CODING JOURNEY</span><h1>Welcome back, ${esc(state.name||'Learner')}.</h1><p>Every line of code takes you one step forward.</p></div><div class="level-badge">${svgIcon('trophy')}<span><small>CURRENT LEVEL</small><b>LEVEL ${level}</b></span></div></section><section class="level-up-card"><div class="level-card-top"><div><span class="eyebrow">LEVEL UP SYSTEM</span><h2>Keep moving forward.</h2><p>Complete lessons and earn XP to unlock your next level.</p></div><div class="xp-total"><b>${state.xp||0}</b><small>TOTAL XP</small></div></div><div class="xp-row"><span>Level ${level}</span><b>${levelXp} / 100 XP</b><span>Level ${level+1}</span></div><div class="xp-track"><i style="width:${levelXp}%"></i></div><div class="level-milestones"><span class="milestone done">${svgIcon('check')} Start</span><span class="milestone ${level>=2?'done':''}">${svgIcon('star')} Level 2</span><span class="milestone ${level>=5?'done':''}">${svgIcon('trophy')} Level 5</span><span class="milestone ${level>=10?'done':''}">${svgIcon('rocket')} Level 10</span></div></section><div class="dash-grid"><section class="dash-panel main-path"><div class="row"><div><span class="eyebrow">YOUR SELECTED PATH</span><h2>${esc(PATHS[state.path][0])}</h2></div><button class="btn secondary small" onclick="renderPath()">Change</button></div><p>${esc(PATHS[state.path][2])}</p><div class="path-progress-label"><span>Course progress</span><b>${done} / 100 levels</b></div><div class="progress"><i style="width:${done}%"></i></div><button class="btn primary-cta" onclick="continueLearning()">${done?'Continue learning':'Start Level 1'} ${svgIcon('arrow')}</button></section><section class="dash-panel daily-panel"><span class="eyebrow">TODAY'S TARGET</span><div class="daily-big">${svgIcon('clock')}<b>${state.dailyGoal}</b><small>MIN / DAY</small></div><p>Small steps add up. Learn at your own pace.</p><button class="btn secondary full" onclick="showDailySetup()">Change daily goal</button></section></div><section class="quick-tools"><div><span class="eyebrow">PRACTICE ZONE</span><h2>Bring your ideas to life.</h2><p>Write HTML, style it with CSS and add behaviour using JavaScript.</p></div><button class="btn primary-cta" onclick="openEditor()">${svgIcon('code')} Open Code Playground ${svgIcon('arrow')}</button></section><section class="dash-bottom"><div class="dash-panel"><span class="eyebrow">YOUR ACTIVITY</span><h2>${total} <small>lessons completed</small></h2><p>${state.bookmarks.length} saved lessons · ${state.xp||0} XP earned</p></div><div class="dash-panel"><span class="eyebrow">LEARNING PREFERENCE</span><h2>${state.skill==='beginner'?'Beginner':state.skill==='intermediate'?'Know the basics':'Some experience'}</h2><p>Daily goal: ${state.dailyGoal} minutes</p></div></section>`}
function showCertificate(){let done=Object.keys(state.done).filter(k=>k.startsWith(state.path+'_')&&state.done[k]).length;app.innerHTML=header()+`<div class="cert"><span class="eyebrow">VIKKU CODE ACADEMY · LEARNING RECORD</span><h1>Progress Certificate</h1><p>This recognises the learning progress of</p><h2>${esc(state.name||'Learner')}</h2><p>Career path: <b>${esc(PATHS[state.path][0])}</b></p><h2>${done} / 100 levels completed</h2><p>This is a local progress summary, not an accredited qualification.</p><button class="btn primary-cta" onclick="levelMap()">Back to roadmap</button></div>`}
function profile(){currentView='profile';setNav(true);let done=Object.keys(state.done).filter(k=>state.done[k]).length,level=Math.floor((state.xp||0)/100)+1;app.innerHTML=header()+`<section class="dash-welcome"><div><span class="eyebrow">LEARNER PROFILE</span><h1>${esc(state.name||'Learner')}</h1><p>Your progress is saved on this device.</p></div><div class="level-badge">${svgIcon('trophy')}<span><small>CURRENT LEVEL</small><b>LEVEL ${level}</b></span></div></section><div class="dash-grid"><div class="dash-panel"><span class="eyebrow">TOTAL XP</span><h2>${state.xp||0} XP</h2></div><div class="dash-panel"><span class="eyebrow">COMPLETED LESSONS</span><h2>${done}</h2></div></div><div class="dash-panel"><h2>Achievements</h2><p>${done>=1?'First lesson completed':'Complete your first lesson to earn an achievement.'} ${done>=10?' · 10 lessons milestone unlocked':''}</p></div><div class="dash-panel"><h2>Saved lessons</h2>${state.bookmarks.length?state.bookmarks.map(k=>{let [pi,li]=k.split('_').map(Number);return `<p>${esc(PATHS[pi]?.[0]||'Path')} · Level ${li+1} <button class="btn secondary small" onclick="state.path=${pi};save();openLesson(${li})">Open</button></p>`}).join(''):'<p>No saved lessons yet.</p>'}</div><div class="dash-panel"><h2>Local account</h2><p>This demo profile and progress are stored in this browser. There is no secure server login or cloud sync.</p><button class="btn secondary" onclick="if(confirm('Sign out? Your progress stays on this device.')){state.name='';state.username='';state.onboardingComplete=false;save();render()} ">Sign out</button></div>`}
function courseMap(){currentView='courses';setNav(true);app.innerHTML=header()+`<span class="eyebrow">LEARNING LIBRARY</span><h1>Choose your next skill.</h1><p>Select a developer path to see its learning roadmap.</p><div class="path-grid">${PATHS.map((p,i)=>pathCard(p,i)).join('')}</div><button class="btn primary-cta full" onclick="levelMap()">Open selected path ${svgIcon('arrow')}</button>`}
function runCode(){let c=collectCode(),frame=$('#preview');if(!frame)return;let safeJs=c.js.replace(/<\/script/gi,'<\\/script'),is3d=$('#previewMode')?.value==='3d';let three=is3d?'<script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r160/three.min.js"><\/script>':'';let doc='<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><style>'+c.css+'</style>'+three+'</head><body>'+c.html+'<script>const send=(type,args)=>parent.postMessage({veekuPreview:true,type,args},"*");console.log=(...a)=>send("log",a);console.error=(...a)=>send("error",a);window.onerror=(m)=>send("error",[m]);<\/script><script>'+safeJs+'<\/script></body></html>';frame.srcdoc=doc;$('#output').textContent='Running your code…';if(!window.__vikkuMessageHandler){window.__vikkuMessageHandler=true;window.addEventListener('message',e=>{let f=$('#preview');if(!f||e.source!==f.contentWindow||!e.data||!e.data.veekuPreview)return;let args=(e.data.args||[]).map(x=>typeof x==='object'?JSON.stringify(x):String(x));$('#output').textContent=(e.data.type==='error'?'Error: ':'')+args.join(' ')})}frame.onload=()=>{if($('#output')?.textContent==='Running your code…')$('#output').textContent=is3d?'3D preview loaded. Drag inside your canvas if your code supports rotation.':'Preview ready. Try interacting with your page.'};save()}

// Practical code tools: simple bilingual line explanations and editable Three.js starter.
function insert3DStarter(){
 const html='<canvas id="scene" style="width:100%;height:100vh;display:block"></canvas>';
 const css='html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#101827}canvas{display:block}';
 const js=`// Create a 3D scene, camera and renderer\nconst scene = new THREE.Scene();\nscene.background = new THREE.Color(0x101827);\nconst camera = new THREE.PerspectiveCamera(70, innerWidth / innerHeight, 0.1, 100);\ncamera.position.z = 4;\nconst renderer = new THREE.WebGLRenderer({ canvas: document.querySelector('#scene'), antialias: true });\nrenderer.setSize(innerWidth, innerHeight);\n\n// Make a 3D box and add it to the scene\nconst geometry = new THREE.BoxGeometry(1.4, 1.4, 1.4);\nconst material = new THREE.MeshStandardMaterial({ color: 0xffcc33, roughness: 0.35 });\nconst cube = new THREE.Mesh(geometry, material);\nscene.add(cube);\nscene.add(new THREE.HemisphereLight(0xffffff, 0x334466, 2));\n\n// Animate the cube\nfunction animate() {\n  requestAnimationFrame(animate);\n  cube.rotation.x += 0.008;\n  cube.rotation.y += 0.012;\n  renderer.render(scene, camera);\n}\nanimate();\n\n// Keep the 3D view responsive\nwindow.addEventListener('resize', () => {\n  camera.aspect = innerWidth / innerHeight;\n  camera.updateProjectionMatrix();\n  renderer.setSize(innerWidth, innerHeight);\n});`;
 writeTab('html',html);writeTab('css',css);writeTab('js',js);state.codes={...state.codes,html,css,js};save();if($('#previewMode'))$('#previewMode').value='3d';switchTab('js');runCode();toast('3D starter added. Edit the JS code to change your model.');
}
function explainCode(){
 const code=readTab(activeTab),lang=$('#explainLanguage')?.value||state.lang||'en',panel=$('#codeExplainPanel'),out=$('#explainContent');if(!panel||!out)return;panel.classList.remove('hidden');
 const words={const:['constant variable','ऐसा variable जिसकी value दोबारा assign नहीं करते'],let:['changeable variable','ऐसा variable जिसकी value बदली जा सकती है'],var:['older variable declaration','variable बनाने का पुराना तरीका'],function:['function definition','बार-बार इस्तेमाल होने वाला काम बनाने का तरीका'],return:['return a value','function से result वापस भेजता है'],if:['condition','शर्त सही होने पर code चलाता है'],else:['alternative branch','शर्त गलत होने पर दूसरा code चलाता है'],for:['loop','किसी काम को बार-बार दोहराता है'],while:['condition loop','जब तक शर्त सही है, code दोहराता है'],true:['boolean true','सही / हाँ वाली boolean value'],false:['boolean false','गलत / नहीं वाली boolean value'],new:['create an instance','किसी class या constructor से नया object बनाता है'],class:['class definition','objects बनाने का blueprint'],this:['current object','मौजूदा object को refer करता है'],async:['asynchronous function','ऐसा function जो asynchronous काम कर सकता है'],await:['wait for async result','async result आने तक इंतजार करता है'],import:['import module','दूसरी file या package से code लाता है'],export:['export module','दूसरी file में code उपलब्ध कराता है'],console:['developer console','debugging के लिए संदेश दिखाने का tool'],log:['print a message','message या value दिखाता है'],document:['web page document','मौजूदा HTML page को represent करता है'],querySelector:['find an HTML element','CSS selector से HTML element खोजता है'],addEventListener:['listen for an event','click जैसे event होने पर code चलाता है'],innerHTML:['read or set HTML','element के अंदर का HTML पढ़ता या बदलता है'],textContent:['read or set text','element का text पढ़ता या बदलता है'],scene:['3D scene','3D objects रखने की जगह'],camera:['3D camera','3D दुनिया को किस angle से देखना है'],renderer:['3D renderer','3D scene को screen पर draw करता है'],Mesh:['3D object','geometry और material से बना 3D object'],BoxGeometry:['box shape','3D डिब्बे जैसी shape बनाता है'],SphereGeometry:['sphere shape','3D गोले जैसी shape बनाता है'],PerspectiveCamera:['perspective camera','दूरी के अनुसार objects का आकार दिखाता है'],requestAnimationFrame:['animation loop','अगली screen frame पर animation चलाता है'],rotation:['rotation','object को घुमाने का angle'],position:['position','object की जगह बताता है'],color:['color value','रंग सेट करता है'],add:['add to scene','object को scene में जोड़ता है'],div:['HTML container','HTML में content का section बनाता है'],h1:['main heading','पेज की मुख्य heading दिखाता है'],h2:['second-level heading','दूसरे स्तर की heading दिखाता है'],p:['paragraph','text का paragraph बनाता है'],button:['button element','click करने वाला button बनाता है'],canvas:['drawing surface','graphics और 3D render करने की जगह देता है'],script:['JavaScript section','HTML में JavaScript जोड़ता है'],style:['CSS section','HTML में CSS जोड़ता है'],id:['unique element identifier','किसी HTML element की अलग पहचान'],class:['CSS class name','एक या अधिक elements पर style लगाने का नाम'],src:['source location','image या script का source बताता है'],href:['link destination','link कहाँ खुलेगा यह बताता है'],display:['display layout','element किस तरह दिखेगा यह तय करता है'],flex:['flex layout','items को flexible row या column में रखता है'],grid:['grid layout','rows और columns वाला layout बनाता है'],position:['positioning mode','element की positioning तय करता है'],background:['background style','element का background सेट करता है'],margin:['outer spacing','element के बाहर की दूरी'],padding:['inner spacing','element के अंदर की दूरी'],width:['element width','element की चौड़ाई'],height:['element height','element की ऊँचाई'],border:['element border','element के चारों ओर किनारा बनाता है'],transform:['visual transform','element को move, rotate या scale करता है'],animation:['CSS animation','element में movement या visual effect जोड़ता है'],overflow:['overflow handling','बाहर निकलने वाले content को कैसे दिखाना है'],alignItems:['cross-axis alignment','items को cross-axis पर align करता है'],justifyContent:['main-axis alignment','items को main-axis पर align करता है']};
 const punct={'=':['assignment: stores a value','किसी variable में value रखता है'],'===':['strict comparison','value और type दोनों की तुलना करता है'],'==':['equality comparison','बराबरी की तुलना करता है'],'+':['addition or string joining','जोड़ता है या text मिलाता है'],'-':['subtraction','घटाता है'],'*':['multiplication','गुणा करता है'],'/':['division','भाग करता है'],'.':['property or method access','किसी property या method तक पहुँचता है'],';':['statement ending','statement समाप्त करता है']};
 const safe=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 out.innerHTML=code.split('\n').map((line,i)=>{
  const trim=line.trim(),comment=trim.startsWith('//')||trim.startsWith('/*')||trim.startsWith('*')||trim.startsWith('<!--');
  const found=Object.keys(words).filter(w=>new RegExp('(^|[^\\w$])'+w.replace(/[.*+?^${}()|[\\]\\\\]/g,'\\$&')+'([^\\w$]|$)').test(trim));
  let meaning;
  if(comment) meaning=lang==='hi'?'यह comment है: इंसान के लिए लिखा नोट, browser इसे execute नहीं करता।':'This is a comment: a note for people; the browser does not execute it.';
  else if(found.length) meaning=found.map(w=>`${w} = ${words[w][lang==='hi'?1:0]}`).join(' · ');
  else meaning=trim?(lang==='hi'?'यह code line आसपास के syntax और values के साथ मिलकर काम करती है।':'This line works together with its surrounding syntax and values.'):(lang==='hi'?'खाली लाइन — code पढ़ना आसान बनाती है।':'Blank line — improves readability.');
  const symbols=Object.keys(punct).filter(k=>trim.includes(k)).slice(0,2);
  if(symbols.length&&!comment)meaning+=' · '+symbols.map(k=>`${k}: ${punct[k][lang==='hi'?1:0]}`).join(' · ');
  return `<article class="explain-line"><div class="explain-code"><span>${i+1}</span><code>${safe(line||' ')}</code></div><p>${safe(meaning)}</p></article>`;
 }).join('');
}
function explainLessonCode(){let d=levelData(state.path,activeLevel);state.codes.js=d.code;state.activeTab='js';openEditor(true);writeTab('js',d.code);if(activeTab!=='js')switchTab('js');explainCode();}

// Restore the correct entry point after the refreshed onboarding functions are defined.
if(state.name&&state.onboardingComplete){dashboard()}else if(state.name){beginSetup()}else{render()}
